import{printedArtwork}from'../../modeling/artwork.js';import{spec}from'./dimensions.js';const sources={front:new URL('./reference-redraw-front.png',import.meta.url).href,back:new URL('./reference-redraw-back.png',import.meta.url).href};export function addStickers(host){const out=[];for(const face of Object.keys(host.nbiot2Assembly.labels)){const v=spec.labels[face],position=[...v.position];if(face==='front')position[2]+=.08;out.push(...printedArtwork(host,{target:host.nbiot2Assembly.labels[face],url:sources[face],size:v.size,position,face,depth:.12,name:'NBIoT2 exact U111-B '+face+' body label',artworkKind:'reference-redraw'})??[]);}return out;}
